// Merges editorial-config.json / validation-config.json / provider-config.json values.
// NOTE: these embedded values must be kept in sync with
// .specify/workflows/cmmc-content-publishing/config/*.json — those files are the
// documented source of truth; n8n Code nodes cannot require() repo files at runtime.
const editorialConfig = {
  brand: 'GovConIC — The Government Contractor Intelligence Center',
  audience: 'mid-market government contractors with approximately $20M-$500M in revenue',
  voiceDescription: 'authoritative, analytical, opinionated, evidence-conscious, practical, non-promotional',
  defaultByline: $env.CMMC_DEFAULT_BYLINE || 'Shahid Shah',
  categoryId: Number($env.WORDPRESS_CATEGORY_ID) || 52,
  formats: [
    'cmmc-policy-or-requirement-update','step-by-step-explainer','contrarian-analysis',
    'data-driven-analysis','composite-contractor-case-study','narrow-cmmc-qa',
    'multi-perspective-source-analysis'
  ],
  multiPerspectiveFormatMarker: 'multi-perspective-source-analysis',
  leadAngles: ['Unobvious', 'Under the Radar', 'Innovative'],
  topics: [
    'SPRS score submission accuracy','POA&M closure timelines under CMMC Level 2',
    'C3PAO surveillance assessment findings trends','Scoping guide boundary disputes for CUI enclaves',
    'DIBCAC assessment readiness gaps','False Claims Act exposure from inaccurate self-attestations',
    'Cyber AB certification backlog impact on small contractors',
    'NIST SP 800-171 control inheritance from cloud providers',
    'CMMC Level 3 assessment cost drivers','Subcontractor flow-down compliance verification burden'
  ],
  avoidedBaselineTopics: [
    'What is CMMC 2.0','CMMC compliance levels overview','CMMC assessment process basics','CMMC certification cost overview'
  ],
  cacheLimits: { recentHeadlines: 15, pendingFollowOnTopics: 30, duplicateHistory: 300 }
};

const validationConfig = {
  paragraphCount: 4, h2Count: 2, statCount: 1, pullquoteCount: 1, calloutCount: 1,
  paragraphWordMin: 20, paragraphWordMax: 50, totalWordMin: 100, totalWordMax: 200, wordCountTolerance: 0,
  subtitleWordMin: 30, subtitleWordMax: 40,
  cmmcTerms: ['CMMC','C3PAO','POA&M','SSP','NIST SP 800-171','NIST SP 800-172','scoring methodology','Level 1','Level 2','Level 3','assessment','certification','compliance','CUI','Controlled Unclassified Information','Defense Industrial Base','Cyber AB','scoping guide'],
  prohibitedPatterns: ['press release','partnership announcement','series a','series b','funding round','raises $','announces partnership','proud to announce','top 10','game-changer','revolutionary','disrupting government','according to a recent report','in a recent announcement','sources say','experts agree','industry leaders say'],
  companionAssets: { minAltTitles: 5, minLinkedinPostChars: 50, minNewsletterSummaryChars: 30, minDiagrams: 1, minFollowOnIdeas: 5 }
};

const providerConfig = {
  model: $env.GROQ_MODEL || 'llama-3.3-70b-versatile',
  baseUrl: $env.GROQ_BASE_URL || 'https://api.groq.com/openai/v1/chat/completions',
  temperature: 0.7, maxTokens: 2000, timeoutMs: 30000, retryCount: 3, retryDelayMs: 5000
};

const wordpressConfig = {
  baseUrl: $env.WORDPRESS_BASE_URL,
  categoryId: Number($env.WORDPRESS_CATEGORY_ID) || 52
};

if (!wordpressConfig.baseUrl) {
  throw new Error('Load Workflow Configuration: WORDPRESS_BASE_URL environment variable is required — failing fast rather than silently proceeding');
}

const dryRun = String($env.CMMC_WORKFLOW_DRY_RUN).toLowerCase() === 'true';
const runId = $execution.id + '-' + $workflow.id;

return [{ json: { editorialConfig, validationConfig, providerConfig, wordpressConfig, dryRun, runId } }];

// Inlined port of .specify/skills/workflow-context-manager/scripts/context-manager.js
// (kept in sync manually; the skill script is the tested source of truth).
const cfg = $input.first().json;
const staticData = $getWorkflowStaticData('global');

function trimToLimit(list, limit) {
  if (!Array.isArray(list)) return [];
  if (typeof limit !== 'number' || limit <= 0) return list.slice();
  return list.length > limit ? list.slice(list.length - limit) : list.slice();
}

const formatRotationIndex = Number.isInteger(staticData.formatRotationIndex) ? staticData.formatRotationIndex : 0;
const leadAngleRotationIndex = Number.isInteger(staticData.leadAngleRotationIndex) ? staticData.leadAngleRotationIndex : 0;

const chosenFormat = cfg.editorialConfig.formats[formatRotationIndex % cfg.editorialConfig.formats.length];
const chosenLeadAngle = cfg.editorialConfig.leadAngles[leadAngleRotationIndex % cfg.editorialConfig.leadAngles.length];

staticData.formatRotationIndex = (formatRotationIndex + 1) % cfg.editorialConfig.formats.length;
staticData.leadAngleRotationIndex = (leadAngleRotationIndex + 1) % cfg.editorialConfig.leadAngles.length;

const recentHeadlines = trimToLimit(staticData.recentHeadlines, cfg.editorialConfig.cacheLimits.recentHeadlines);
const pendingFollowOnTopics = trimToLimit(staticData.pendingFollowOnTopics, cfg.editorialConfig.cacheLimits.pendingFollowOnTopics);
const avoidedTopics = cfg.editorialConfig.avoidedBaselineTopics.concat(pendingFollowOnTopics);

const memorySnapshot = {
  postedUrls: staticData.postedUrls || [],
  postedTitles: staticData.postedTitles || [],
  postedContentHashes: staticData.postedContentHashes || [],
  recentHeadlines
};

return [{
  json: Object.assign({}, cfg, {
    selectedFormat: chosenFormat,
    selectedLeadAngle: chosenLeadAngle,
    recentHeadlines,
    avoidedTopics,
    memorySnapshot
  })
}];

// Inlined port of .specify/skills/source-content-extractor/scripts/source-extractor.js
const item = $input.first().json;
const SCRIPT_STYLE_RE = /<(script|style)[^>]*>[\s\S]*?<\/\1>/gi;
const TAG_RE = /<[^>]+>/g;

function sanitizeToPlainText(html) {
  if (!html) return '';
  return String(html)
    .replace(SCRIPT_STYLE_RE, ' ')
    .replace(TAG_RE, ' ')
    .replace(/&nbsp;/gi, ' ').replace(/&amp;/gi, '&').replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>').replace(/&quot;/gi, '"').replace(/&#39;/gi, "'")
    .replace(/\s+/g, ' ').trim();
}

const title = sanitizeToPlainText(item.sourceTitle);
const content = sanitizeToPlainText(item.sourceContentHtml);
const usable = title.length > 0 && content.length >= 40;

return [{ json: Object.assign({}, item, { normalizedSourceArticle: { title, url: item.sourceUrl || '', content, usable } }) }];

// Inlined port of .specify/skills/topic-angle-selector/scripts/topic-angle-selector.js
const item = $input.first().json;

function normalize(v) { return String(v || '').trim().toLowerCase(); }

const isMultiPerspective = item.selectedFormat === item.editorialConfig.multiPerspectiveFormatMarker;

if (isMultiPerspective) {
  const source = item.normalizedSourceArticle;
  if (!source || !source.usable) {
    return [{ json: Object.assign({}, item, { rejected: true, reason: 'source-unusable', generationMode: 'multiPerspective' }) }];
  }
}

const excluded = new Set((item.avoidedTopics || []).map(normalize));
let eligible = item.editorialConfig.topics.filter((t) => !excluded.has(normalize(t)));
if (eligible.length === 0) eligible = item.editorialConfig.topics;
const topic = eligible[0];

return [{
  json: Object.assign({}, item, {
    rejected: false,
    generationMode: isMultiPerspective ? 'multiPerspective' : 'standard',
    topic,
    leadAngle: item.selectedLeadAngle,
    format: item.selectedFormat
  })
}];

// Inlined port of .specify/skills/workflow-observability-reporter/scripts/reporter.js (status: skipped_duplicate)
const item = $input.first().json;
return [{
  json: {
    runId: item.runId, stage: 'topic-selection', status: 'skipped_duplicate',
    failureCode: item.reason || 'source-unusable',
    message: 'Run skipped: ' + (item.reason || 'source-unusable'),
    timestamp: new Date().toISOString()
  }
}];

// Inlined port of .specify/skills/multi-perspective-planner/scripts/multi-perspective-planner.js
const item = $input.first().json;

const PERSPECTIVES = [
  { perspective: 'Executive', perspectiveInstructions: 'Write for CEOs, CIOs, CTOs, CISOs, boards, and government contractors. Focus on strategic risk, business impact, and the decisions leadership needs to make.' },
  { perspective: 'Engineering', perspectiveInstructions: 'Write for DevSecOps and engineering teams. Focus on evidence automation, secure software development, continuous compliance, AI-assisted engineering, and operational excellence.' },
  { perspective: 'Compliance', perspectiveInstructions: 'Write for compliance and risk teams. Focus on CMMC, NIST SP 800-171, DIBCAC assessments, False Claims Act implications, evidence generation, and audit readiness.' }
];

const groupId = item.runId + '-multiPerspective';

return PERSPECTIVES.map((p) => ({
  json: Object.assign({}, item, {
    format: p.perspective + ' perspective: ' + p.perspectiveInstructions,
    perspective: p.perspective,
    perspectiveInstructions: p.perspectiveInstructions,
    groupId,
    sourceReference: item.normalizedSourceArticle
  })
}));

// Inlined port of .specify/skills/cmmc-editorial-prompt-builder/scripts/prompt-builder.js
const item = $input.first().json;
const ec = item.editorialConfig; const vc = item.validationConfig;

const systemPrompt = 'You are a professional journalist writing for ' + ec.brand + ', an editorial publication for ' + ec.audience + '.\n' +
'Voice: ' + ec.voiceDescription + '\n' +
'Word count requirement (STRICT — hard pass/fail gate, not a suggestion):\n' +
'- The body MUST contain EXACTLY ' + vc.paragraphCount + ' paragraph ("p") blocks, EXACTLY ' + vc.h2Count + ' "h2" blocks, EXACTLY ' + vc.statCount + ' "stat" block, EXACTLY ' + vc.pullquoteCount + ' "pullquote" block, and EXACTLY ' + vc.calloutCount + ' "callout" block. "list" blocks are optional.\n' +
'- Each paragraph MUST contain between ' + vc.paragraphWordMin + ' and ' + vc.paragraphWordMax + ' words.\n' +
'- The total word count across all "p" blocks MUST be between ' + vc.totalWordMin + ' and ' + vc.totalWordMax + ' words. There are no exceptions to this range.\n' +
'- Report your final total as an integer in the "bodyWordCount" field — it must match the actual sum across all "p" blocks.\n' +
'- Numbers: always sourced inline. Quotes: attribute precisely; never invent a quote from a specific named real person.\n' +
'- Tone: contrarian, thought-leadership. Avoid press-release/news-report phrasing.\n' +
'- Headline uniqueness: the headline MUST be clearly different from every headline in the recent headlines list below.\n' +
'- Subtitle requirement (STRICT, REQUIRED FIELD): you MUST include a non-empty "subtitle" field, 30-40 words, distinct from both "dek" and "kicker".\n' +
'You must return a single JSON object with ALL of: headline, slug, section, kicker, subtitle, dek, byline, date, readMinutes, bodyWordCount, body, altTitles (5+), linkedinPost (50+ chars), newsletterSummary (30+ chars), suggestedDiagrams (1+), followOnIdeas (5+). Do not return any text outside this JSON object.';

let userPrompt = 'Write a piece with the following parameters:\nTopic: ' + item.topic + '\nFormat: ' + item.format + '\nLead angle: ' + item.leadAngle + '\n\n' +
'IMPORTANT: avoid these already-covered subjects: ' + ((item.avoidedTopics || []).join('; ') || 'none') + '\n' +
'Recent headlines already used — be clearly distinct from all of these: ' + ((item.recentHeadlines || []).join(' | ') || 'none') + '\n';

if (item.perspective) {
  const src = item.sourceReference || {};
  userPrompt += '\nYou are analyzing a source article as a senior federal technology journalist, CISO, CTO, CMMC assessor, software architect, and compliance expert. Do NOT summarize — analyze deeply.\n' +
    'Source article title: ' + (src.title || '') + '\nSource article URL: ' + (src.url || '') + '\n' +
    "This piece's perspective (" + item.perspective + '): ' + item.perspectiveInstructions + '\n';
}
userPrompt += '\nReturn ONLY the JSON object matching the schema above.';

const payload = {
  model: item.providerConfig.model,
  response_format: { type: 'json_object' },
  max_tokens: item.providerConfig.maxTokens,
  temperature: item.providerConfig.temperature,
  messages: [ { role: 'system', content: systemPrompt }, { role: 'user', content: userPrompt } ]
};

return [{ json: Object.assign({}, item, { llmRequestBody: JSON.stringify(payload) }) }];

// Inlined port of .specify/skills/article-response-normalizer/scripts/normalize-article.js
const item = $input.first().json;
const raw = item.choices && item.choices[0] && item.choices[0].message ? item.choices[0].message.content : '';
const upstream = item;

function asArray(val) {
  if (Array.isArray(val)) return val;
  if (typeof val === 'string') return val.split(/\r?\n|\|/).map((s) => s.trim()).filter(Boolean);
  return [];
}
function pickField(data, keys) {
  for (const k of keys) if (data[k] !== undefined && data[k] !== null && data[k] !== '') return data[k];
  return undefined;
}
function countParagraphWords(body) {
  if (!Array.isArray(body)) return 0;
  return body.filter((b) => b && b.type === 'p' && typeof b.text === 'string')
    .reduce((total, b) => total + b.text.trim().split(/\s+/).filter(Boolean).length, 0);
}

let parsed;
try { parsed = JSON.parse(raw); } catch (err) {
  return [{ json: Object.assign({}, upstream, { normalizationValid: false, normalizationError: 'invalid_json: ' + err.message, article: null }) }];
}
if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
  return [{ json: Object.assign({}, upstream, { normalizationValid: false, normalizationError: 'invalid_shape', article: null }) }];
}

const body = Array.isArray(parsed.body) ? parsed.body : (Array.isArray(parsed.content) ? parsed.content : (Array.isArray(parsed.article) ? parsed.article : (Array.isArray(parsed.sections) ? parsed.sections : [])));
const calculatedBodyWordCount = countParagraphWords(body);

const article = {
  headline: parsed.headline || '', slug: parsed.slug || '', section: parsed.section || '',
  kicker: parsed.kicker || '', subtitle: parsed.subtitle || '', dek: parsed.dek || '',
  byline: parsed.byline || upstream.editorialConfig.defaultByline, date: parsed.date || new Date().toISOString().slice(0, 10),
  readMinutes: typeof parsed.readMinutes === 'number' ? parsed.readMinutes : Number(parsed.readMinutes) || 0,
  bodyWordCount: calculatedBodyWordCount, body,
  altTitles: asArray(pickField(parsed, ['altTitles', 'alternativeTitles', 'titleOptions', 'titles'])),
  linkedinPost: pickField(parsed, ['linkedinPost', 'linkedInPost', 'linkedin_post']) || '',
  newsletterSummary: pickField(parsed, ['newsletterSummary', 'newsletter_summary', 'digestSummary']) || '',
  suggestedDiagrams: asArray(pickField(parsed, ['suggestedDiagrams', 'diagramIdeas', 'diagrams'])),
  followOnIdeas: asArray(pickField(parsed, ['followOnIdeas', 'followOnArticles', 'relatedArticleIdeas']))
};

const requiredFields = ['headline', 'slug', 'section', 'kicker', 'subtitle', 'dek', 'byline', 'date', 'readMinutes'];
const missing = requiredFields.filter((f) => !article[f]);
const normalizationValid = missing.length === 0 && Array.isArray(body) && body.length > 0;

return [{ json: Object.assign({}, upstream, { normalizationValid, normalizationError: normalizationValid ? null : 'missing_fields: ' + missing.join(','), article }) }];

// Inlined port of .specify/skills/article-blocks-to-html/scripts/blocks-to-html.js
const item = $input.first().json;
const SUPPORTED = new Set(['p','h2','h3','h4','stat','pullquote','list','callout']);

function esc(v) { return String(v == null ? '' : v).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;'); }
function render(b) {
  switch (b.type) {
    case 'p': return '<p>' + esc(b.text) + '</p>';
    case 'h2': return '<h2>' + esc(b.text) + '</h2>';
    case 'h3': return '<h3>' + esc(b.text) + '</h3>';
    case 'h4': return '<h4>' + esc(b.text) + '</h4>';
    case 'stat': return '<div class="stat"><span class="stat-value">' + esc(b.value) + '</span><span class="stat-label">' + esc(b.label) + '</span></div>';
    case 'pullquote': return '<blockquote>' + esc(b.text) + '</blockquote>';
    case 'list': return '<ul>' + (b.items || []).map((i) => '<li>' + esc(i) + '</li>').join('') + '</ul>';
    case 'callout': return '<div class="callout">' + esc(b.text) + '</div>';
    default: return null;
  }
}

if (!item.normalizationValid) {
  return [{ json: Object.assign({}, item, { htmlValid: false, html: null }) }];
}

const body = item.article.body || [];
const errors = [];
const parts = [];
body.forEach((b, i) => {
  if (!b || typeof b.type !== 'string') { errors.push('block ' + i + ' has no type'); return; }
  if (!SUPPORTED.has(b.type)) { errors.push('block ' + i + ' unsupported type ' + b.type); return; }
  parts.push(render(b));
});

if (errors.length > 0) {
  return [{ json: Object.assign({}, item, { htmlValid: false, html: null, htmlErrors: errors }) }];
}

const html = parts.join('\n');
return [{ json: Object.assign({}, item, { htmlValid: true, html }) }];

// Inlined port of .specify/skills/cmmc-oat-validator/scripts/oat-validator.js
const item = $input.first().json;

if (!item.normalizationValid || !item.htmlValid) {
  return [{ json: Object.assign({}, item, { oatPassed: false, oatErrors: [{ code: 'upstream_failure', message: item.normalizationError || (item.htmlErrors || []).join('; ') }] }) }];
}

const article = item.article; const vc = item.validationConfig; const memory = item.memorySnapshot || {};

function escapeRegex(s) { return String(s).replace(/[.*+?^${}()|[\]\\]/g, '\\$&'); }
function wholeTerm(term) { return new RegExp('(?<![a-zA-Z0-9])' + escapeRegex(term) + '(?![a-zA-Z0-9])', 'i'); }
function normHeadline(h) { return String(h || '').toLowerCase().replace(/[^a-z0-9 ]/g, '').replace(/\s+/g, ' ').trim(); }
function normContent(c) { return String(c || '').toLowerCase().replace(/<[^>]+>/g, ' ').replace(/[^a-z0-9 ]/g, '').replace(/\s+/g, ' ').trim(); }
function simpleHash(s) { let h = 0; for (let i=0;i<s.length;i++) h=(Math.imul(31,h)+s.charCodeAt(i))|0; return (h>>>0).toString(16); }
function wc(t) { const s=(t||'').trim(); return s ? s.split(/\s+/).filter(Boolean).length : 0; }
function sixWordOverlap(a, b) { const words=a.split(' ').filter(Boolean); for (let i=0;i<=words.length-6;i++){const w=words.slice(i,i+6).join(' '); if (w && b.includes(w)) return true;} return false; }

const errors = [];

if (!article.headline || article.headline.trim().length < 5) errors.push({ code: 'headline_too_short', message: 'headline must be at least 5 characters' });
if (!/^[a-z0-9]+(-[a-z0-9]+)*$/.test(article.slug || '')) errors.push({ code: 'invalid_slug', message: 'slug must be URL-safe' });

const counts = { p: 0, h2: 0, stat: 0, pullquote: 0, callout: 0 };
const paraCounts = [];
(article.body || []).forEach((b) => { if (b.type in counts) counts[b.type]++; if (b.type === 'p') paraCounts.push(wc(b.text)); });
if (counts.p !== vc.paragraphCount) errors.push({ code: 'wrong_paragraph_count', message: 'expected ' + vc.paragraphCount + ' p blocks, found ' + counts.p });
if (counts.h2 !== vc.h2Count) errors.push({ code: 'wrong_h2_count', message: 'expected ' + vc.h2Count + ' h2 blocks, found ' + counts.h2 });
if (counts.stat !== vc.statCount) errors.push({ code: 'wrong_stat_count', message: 'expected ' + vc.statCount + ' stat block' });
if (counts.pullquote !== vc.pullquoteCount) errors.push({ code: 'wrong_pullquote_count', message: 'expected ' + vc.pullquoteCount + ' pullquote block' });
if (counts.callout !== vc.calloutCount) errors.push({ code: 'wrong_callout_count', message: 'expected ' + vc.calloutCount + ' callout block' });
paraCounts.forEach((c, i) => { if (c < vc.paragraphWordMin || c > vc.paragraphWordMax) errors.push({ code: 'paragraph_word_count_out_of_range', message: 'paragraph ' + (i+1) + ' has ' + c + ' words' }); });
const total = paraCounts.reduce((a,b)=>a+b,0);
const tol = vc.wordCountTolerance || 0;
if (total < vc.totalWordMin - tol || total > vc.totalWordMax + tol) errors.push({ code: 'total_word_count_out_of_range', message: 'total ' + total + ' outside ' + vc.totalWordMin + '-' + vc.totalWordMax });
if (article.bodyWordCount !== total) errors.push({ code: 'body_word_count_mismatch', message: 'bodyWordCount mismatch' });

if (!article.subtitle) errors.push({ code: 'missing_subtitle', message: 'subtitle is mandatory' });
else {
  const sw = wc(article.subtitle);
  if (sw < vc.subtitleWordMin || sw > vc.subtitleWordMax) errors.push({ code: 'subtitle_word_count_out_of_range', message: 'subtitle has ' + sw + ' words' });
  if (article.subtitle.trim() === (article.dek||'').trim()) errors.push({ code: 'subtitle_matches_dek', message: 'subtitle must differ from dek' });
  if (article.subtitle.trim() === (article.kicker||'').trim()) errors.push({ code: 'subtitle_matches_kicker', message: 'subtitle must differ from kicker' });
}

const searchable = [article.headline, article.subtitle, article.dek, item.topic].concat((article.body||[]).filter(b=>b.text).map(b=>b.text)).join(' ');
const matchedTerms = (vc.cmmcTerms||[]).filter((t)=>wholeTerm(t).test(searchable));
if (matchedTerms.length === 0) errors.push({ code: 'not_cmmc_relevant', message: 'no approved CMMC term found' });

const normalizedIncoming = normHeadline(article.headline);
const bodyText = (article.body||[]).map(b=>b.text||'').join(' ');
const contentHash = simpleHash(normContent(bodyText));
if (item.normalizedSourceArticle && item.normalizedSourceArticle.url && (memory.postedUrls||[]).includes(item.normalizedSourceArticle.url)) {
  errors.push({ code: 'duplicate_source_url', message: 'source URL already posted' });
}
(memory.postedTitles||[]).forEach((stored) => { if (normHeadline(stored) === normalizedIncoming) errors.push({ code: 'duplicate_exact_headline', message: 'exact headline duplicate' }); });
(memory.postedTitles||[]).forEach((stored) => { if (sixWordOverlap(normalizedIncoming, normHeadline(stored))) errors.push({ code: 'duplicate_headline_overlap', message: 'six-word headline overlap' }); });
if ((memory.postedContentHashes||[]).includes(contentHash)) errors.push({ code: 'duplicate_content_hash', message: 'content hash duplicate' });
(memory.recentHeadlines||[]).forEach((h) => { if (sixWordOverlap(normalizedIncoming, normHeadline(h))) errors.push({ code: 'duplicate_recent_headline_similarity', message: 'recent headline overlap' }); });

const searchableLower = searchable.toLowerCase();
(vc.prohibitedPatterns||[]).forEach((p) => { if (searchableLower.includes(p.toLowerCase())) errors.push({ code: 'prohibited_pattern', message: 'matched prohibited pattern: ' + p }); });

const ca = vc.companionAssets;
if ((article.altTitles||[]).length < ca.minAltTitles) errors.push({ code: 'insufficient_alt_titles', message: 'need at least ' + ca.minAltTitles + ' alt titles' });
if ((article.linkedinPost||'').length < ca.minLinkedinPostChars) errors.push({ code: 'linkedin_post_too_short', message: 'linkedinPost too short' });
if ((article.newsletterSummary||'').length < ca.minNewsletterSummaryChars) errors.push({ code: 'newsletter_summary_too_short', message: 'newsletterSummary too short' });
if ((article.suggestedDiagrams||[]).length < ca.minDiagrams) errors.push({ code: 'insufficient_diagrams', message: 'need at least ' + ca.minDiagrams + ' diagram(s)' });
if ((article.followOnIdeas||[]).length < ca.minFollowOnIdeas) errors.push({ code: 'insufficient_follow_on_ideas', message: 'need at least ' + ca.minFollowOnIdeas + ' follow-on ideas' });

return [{ json: Object.assign({}, item, { oatPassed: errors.length === 0, oatErrors: errors, oatContentHash: contentHash, oatMatchedTerms: matchedTerms }) }];

// Never forwards the article/debug content to publication — only a structured log event.
const item = $input.first().json;
return [{
  json: {
    runId: item.runId, articleId: item.article ? item.article.slug : null, groupId: item.groupId || null,
    stage: 'oat-validation', status: 'oat_failed', retryCount: 0,
    failureCode: (item.oatErrors && item.oatErrors[0] && item.oatErrors[0].code) || 'unknown',
    message: JSON.stringify((item.oatErrors||[]).map((e)=>e.message)).slice(0,300),
    timestamp: new Date().toISOString()
  }
}];

const item = $input.first().json;
return [{
  json: {
    runId: item.runId, articleId: item.article.slug, groupId: item.groupId || null,
    stage: 'dry-run', status: 'dry_run_complete', retryCount: 0, failureCode: null,
    message: 'Dry run — would publish "' + item.article.headline + '" as a draft. No WordPress call made, memory unchanged.',
    timestamp: new Date().toISOString(), wouldPublish: { title: item.article.headline, categories: [item.wordpressConfig.categoryId] }
  }
}];

// Inlined port of .specify/skills/publication-memory-updater/scripts/memory-updater.js
// Runs ONLY after Publish WordPress Draft has returned a successful response (n8n stops
// this branch automatically on an HTTP error, since continueOnFail is not set) — resolves
// research.md R9: caches are never updated before a confirmed publish.
const item = $input.first().json;
const wpResponse = { id: item.id, status: item.status };
const staticData = $getWorkflowStaticData('global');

function appendDedupTrim(list, value, limit) {
  const arr = Array.isArray(list) ? list.slice() : [];
  if (value && !arr.includes(value)) arr.push(value);
  return (typeof limit === 'number' && limit > 0 && arr.length > limit) ? arr.slice(arr.length - limit) : arr;
}

const limits = item.editorialConfig.cacheLimits;
const followOnTitles = (item.article.followOnIdeas || []).map((i) => (typeof i === 'string' ? i : i.title)).filter(Boolean);

staticData.recentHeadlines = appendDedupTrim(staticData.recentHeadlines, item.article.headline, limits.recentHeadlines);
staticData.postedTitles = appendDedupTrim(staticData.postedTitles, item.article.headline, limits.duplicateHistory);
staticData.postedContentHashes = appendDedupTrim(staticData.postedContentHashes, item.oatContentHash, limits.duplicateHistory);
if (item.normalizedSourceArticle && item.normalizedSourceArticle.url) {
  staticData.postedUrls = appendDedupTrim(staticData.postedUrls, item.normalizedSourceArticle.url, limits.duplicateHistory);
}
let pending = Array.isArray(staticData.pendingFollowOnTopics) ? staticData.pendingFollowOnTopics.slice() : [];
followOnTitles.forEach((t) => { pending = appendDedupTrim(pending, t, limits.pendingFollowOnTopics); });
staticData.pendingFollowOnTopics = pending;
staticData.oatPassedCount = (Number.isFinite(staticData.oatPassedCount) ? staticData.oatPassedCount : 0) + 1;
staticData.lastPublicationTimestamp = new Date().toISOString();

return [{
  json: Object.assign({}, item, {
    publicationRecord: { postId: wpResponse.id, status: wpResponse.status || 'draft', categoryId: item.wordpressConfig.categoryId, publishedAt: staticData.lastPublicationTimestamp, sourceUrl: (item.normalizedSourceArticle||{}).url || null, groupId: item.groupId || null }
  })
}];

const item = $input.first().json;
return [{
  json: {
    runId: item.runId, articleId: item.article.slug, groupId: item.groupId || null,
    stage: 'publication', status: 'published', retryCount: 0, failureCode: null,
    message: 'WordPress draft ' + item.publicationRecord.postId + ' created for "' + item.article.headline + '"',
    timestamp: new Date().toISOString()
  }
}];

// Final execution summary — aggregates all Log* events seen this run via workflow static data counters.
const staticData = $getWorkflowStaticData('global');
return [{
  json: {
    status: 'execution_report',
    oatPassedCountAllTime: staticData.oatPassedCount || 0,
    lastPublicationTimestamp: staticData.lastPublicationTimestamp || null,
    recentHeadlines: staticData.recentHeadlines || [],
    timestamp: new Date().toISOString()
  }
}];
